// func sumAVX2Kernel(src uintptr, n int) float32
// Requires: AVX, SSE
TEXT ·sumAVX2Kernel(SB), NOSPLIT, $0-20
	MOVQ   src+0(FP), AX
	MOVQ   n+8(FP), CX
	VXORPS Y0, Y0, Y0

sum_loop:
	CMPQ    CX, $0x08
	JL      sum_tail
	VMOVUPS (AX), Y1
	VADDPS  Y1, Y0, Y0
	ADDQ    $0x20, AX
	SUBQ    $0x08, CX
	JMP     sum_loop

sum_tail:
	VEXTRACTF128 $0x00, Y0, X1
	VEXTRACTF128 $0x01, Y0, X0
	VADDPS       X1, X0, X0
	VMOVSHDUP    X0, X1
	VADDPS       X1, X0, X0
	VMOVHLPS     X0, X0, X1
	VADDSS       X1, X0, X0
	MOVSS        X0, ret+16(FP)
	VZEROUPPER
	RET

