// func cosine8AVX2(a uintptr, b uintptr) (dot float32, normA float32, normB float32)
// Requires: AVX, SSE
TEXT ·cosine8AVX2(SB), NOSPLIT, $0-28
	MOVQ         a+0(FP), AX
	MOVQ         b+8(FP), CX
	VMOVUPS      (AX), Y0
	VMOVUPS      (CX), Y1
	VMULPS       Y0, Y1, Y2
	VMULPS       Y0, Y0, Y0
	VMULPS       Y1, Y1, Y1
	VEXTRACTF128 $0x00, Y2, X3
	VEXTRACTF128 $0x01, Y2, X2
	VADDPS       X3, X2, X2
	VMOVSHDUP    X2, X3
	VADDPS       X3, X2, X2
	VMOVHLPS     X2, X2, X3
	VADDSS       X3, X2, X2
	MOVSS        X2, dot+16(FP)
	VEXTRACTF128 $0x00, Y0, X2
	VEXTRACTF128 $0x01, Y0, X0
	VADDPS       X2, X0, X0
	VMOVSHDUP    X0, X2
	VADDPS       X2, X0, X0
	VMOVHLPS     X0, X0, X2
	VADDSS       X2, X0, X0
	MOVSS        X0, normA+20(FP)
	VEXTRACTF128 $0x00, Y1, X0
	VEXTRACTF128 $0x01, Y1, X1
	VADDPS       X0, X1, X1
	VMOVSHDUP    X1, X0
	VADDPS       X0, X1, X1
	VMOVHLPS     X1, X1, X0
	VADDSS       X0, X1, X1
	MOVSS        X1, normB+24(FP)
	VZEROUPPER
	RET

