// func matMulAVX2Kernel(a uintptr, b uintptr, dst uintptr, m int, n int, k int)
// Requires: AVX, AVX2, FMA3
TEXT ·matMulAVX2Kernel(SB), NOSPLIT, $0-48
	MOVQ a+0(FP), AX
	MOVQ b+8(FP), CX
	MOVQ dst+16(FP), DX
	MOVQ m+24(FP), BX
	MOVQ n+32(FP), SI
	MOVQ k+40(FP), DI
	XORQ R8, R8

m_loop:
	CMPQ R8, BX
	JE   m_done
	XORQ R9, R9

k_loop:
	CMPQ         R9, DI
	JE           k_done
	MOVQ         R8, R10
	IMULQ        DI, R10
	ADDQ         R9, R10
	VMOVSS       (AX)(R10*4), X0
	VBROADCASTSS X0, Y0
	XORQ         R10, R10

n_loop:
	CMPQ        R10, SI
	JGE         n_done
	MOVQ        R9, R11
	IMULQ       SI, R11
	ADDQ        R10, R11
	MOVQ        R8, R12
	IMULQ       SI, R12
	ADDQ        R10, R12
	VMOVUPS     (CX)(R11*4), Y1
	VMOVUPS     (DX)(R12*4), Y2
	VFMADD231PS Y0, Y1, Y2
	VMOVUPS     Y2, (DX)(R12*4)
	ADDQ        $0x08, R10
	JMP         n_loop

n_done:
	INCQ R9
	JMP  k_loop

k_done:
	INCQ R8
	JMP  m_loop

m_done:
	VZEROUPPER
	RET

